export const getFreeUrl = (params?: FreeParams,) => {
  const normalizedParams = new URLSearchParams();

  Object.entries(params || {}).forEach(([key, value]) => {
    const explodeParameters = ["fq","bq"];

    if (Array.isArray(value) && explodeParameters.includes(key)) {
      value.forEach((v) => {
        normalizedParams.append(key, v === null ? 'null' : String(v));
      });
      return;
    }

    if (value !== undefined) {
      normalizedParams.append(key, value === null ? 'null' : String(value))
    }
  });

  const stringifiedParams = normalizedParams.toString();

  return stringifiedParams.length > 0 ? `https://api.pdok.nl/bzk/locatieserver/search/v3_1/free?${stringifiedParams}` : `https://api.pdok.nl/bzk/locatieserver/search/v3_1/free`
}

/**
 * @summary De Free API biedt de mogelijkheid om vrij te zoeken (klassiek geocoderen), waar zonder
tussenkomst van suggesties de API direct resultaten teruggeeft op basis van de zoekopdracht.

 */
export const free = async (params?: FreeParams, options?: RequestInit): Promise<freeResponse> => {

  const res = await fetch(getFreeUrl(params),
  {
    ...options,
    method: 'GET'


  }
)

  const contentType = (res.headers.get('content-type') ?? '').toLowerCase();
  const body = [204, 205, 304].includes(res.status) ? null : await res.text();

  const data: freeResponse['data'] = body ? (contentType.includes('json') ? JSON.parse(body) : body) : {}
  return { data, status: res.status, headers: res.headers } as freeResponse
}




export const getFreeKey = (params?: FreeParams,) => [`https://api.pdok.nl/bzk/locatieserver/search/v3_1/free`, ...(params ? [params]: [])] as const;

export type FreeQueryResult = NonNullable<Awaited<ReturnType<typeof free>>>

/**
 * @summary De Free API biedt de mogelijkheid om vrij te zoeken (klassiek geocoderen), waar zonder
tussenkomst van suggesties de API direct resultaten teruggeeft op basis van de zoekopdracht.

 */
export const useFree = <TError = Promise<Free400One | string>>(
  params?: FreeParams, options?: { swr?:SWRConfiguration<Awaited<ReturnType<typeof free>>, TError> & { swrKey?: Key, enabled?: boolean }, fetch?: RequestInit }
) => {
  const {swr: swrOptions, fetch: fetchOptions} = options ?? {}

  const isEnabled = swrOptions?.enabled !== false
  const swrKey = swrOptions?.swrKey ?? (() => isEnabled ? getFreeKey(params) : null);
  const swrFn = () => free(params, fetchOptions)

  const query = useSwr<Awaited<ReturnType<typeof swrFn>>, TError>(swrKey, swrFn, swrOptions)

  return {
    swrKey,
    ...query
  }
}

